class Solution {
    public int oddEvenJumps(int[] arr) {
        int n=arr.length;
        if(n<=1) return n;
        Integer[] idx=new Integer[n];
        for(int i=0;i<n;i++) idx[i]=i;
        Arrays.sort(idx,(a,b)->{ int c=Integer.compare(arr[a],arr[b]); return c!=0?c:Integer.compare(a,b); });
        int[] nextOdd=buildNext(idx,n);
        for(int i=0;i<n;i++) idx[i]=i;
        Arrays.sort(idx,(a,b)->{ int c=Integer.compare(arr[b],arr[a]); return c!=0?c:Integer.compare(a,b); });
        int[] nextEven=buildNext(idx,n);
        boolean[] odd=new boolean[n], even=new boolean[n];
        odd[n-1]=true; even[n-1]=true;
        for(int i=n-2;i>=0;i--){
            if(nextOdd[i]!=-1) odd[i]=even[nextOdd[i]];
            if(nextEven[i]!=-1) even[i]=odd[nextEven[i]];
        }
        int ans=0; for(boolean x:odd) if(x) ans++; return ans;
    }
    private int[] buildNext(Integer[] idx,int n){
        int[] next=new int[n]; Arrays.fill(next,-1);
        int[] stack=new int[n]; int top=0;
        for(int x:idx){ while(top>0 && stack[top-1]<x) next[stack[--top]]=x; stack[top++]=x; }
        return next;
    }
}

