import sys, json

class Solution:
    def oddEvenJumps(self, arr):
        n = len(arr)
        if n <= 1:
            return n

        def build_next(indices):
            nxt = [-1] * n
            stack = []
            for i in indices:
                while stack and stack[-1] < i:
                    nxt[stack.pop()] = i
                stack.append(i)
            return nxt

        indices = sorted(range(n), key=lambda i: (arr[i], i))
        next_odd = build_next(indices)
        indices = sorted(range(n), key=lambda i: (-arr[i], i))
        next_even = build_next(indices)

        odd_good = [False] * n
        even_good = [False] * n
        odd_good[-1] = even_good[-1] = True
        for i in range(n - 2, -1, -1):
            if next_odd[i] != -1:
                odd_good[i] = even_good[next_odd[i]]
            if next_even[i] != -1:
                even_good[i] = odd_good[next_even[i]]
        return sum(odd_good)

